use std::collections::BTreeMap;use artifactum_core::{provider_error,AcquireContext,AcquisitionPlan,ArtifactPath,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,ResolvedFile,ResolvedRevision,Resolution};use artifactum_provider_api::{apply_headers,checked,client,encode_segment,header_token,plan,profile_value};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct GitLabProvider;
#[async_trait]impl ArtifactProvider for GitLabProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"gitlab".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["gitlab".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,c:&ResolveContext)->artifactum_core::Result<Resolution>{if c.offline{return Err(provider_error("gitlab","cannot resolve while offline"));}let(project,path)=r.reference.locator().split_once('#').ok_or_else(||provider_error("gitlab","expected gitlab:<namespace/project>#<path>"))?;let requested=r.revision.as_deref().unwrap_or("HEAD");let base=profile_value(c,"api_base").unwrap_or("https://gitlab.com/api/v4").trim_end_matches('/');let headers=header_token(c.profile.as_ref(),"token_env","GITLAB_TOKEN","PRIVATE-TOKEN");let url=format!("{base}/projects/{}/repository/files/{}/raw?ref={}&lfs=true",encode_segment(project),path.split('/').map(encode_segment).collect::<Vec<_>>().join("%2F"),encode_segment(requested));let response=checked("gitlab",apply_headers(client()?.head(&url),&headers).send().await.map_err(|e|provider_error("gitlab",e))?).await?;let size=response.content_length();let commit=response.headers().get("x-gitlab-commit-id").and_then(|v|v.to_str().ok()).unwrap_or(requested).to_owned();let rf=ResolvedFile{path:ArtifactPath::new(path)?,size,digests:Default::default(),media_type:response.headers().get(reqwest::header::CONTENT_TYPE).and_then(|v|v.to_str().ok()).map(str::to_owned),source:serde_json::json!({"url":url})};Ok(Resolution{provider:"gitlab".into(),canonical_ref:format!("gitlab:{project}#{path}"),revision:Some(ResolvedRevision{id:commit,requested:r.revision.clone()}),files:vec![rf],provider_state:serde_json::Value::Null,metadata:BTreeMap::new()})}async fn prepare_acquisition(&self,f:&ResolvedFile,c:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{let url=f.source.get("url").and_then(|v|v.as_str()).ok_or_else(||provider_error("gitlab","missing raw URL"))?;let headers=header_token(c.profile.as_ref(),"token_env","GITLAB_TOKEN","PRIVATE-TOKEN");Ok(plan(url,headers))}}
pub fn provider()->GitLabProvider{GitLabProvider}
